const $ = s => document.querySelector(s);
const KEY = 'runelana-demo-v1';
const defaults = {started:false,runes:120,xp:0,last:Date.now(),path:'gather',owned:[],equipped:"Traveler's cloak"};
let state = {...defaults};
try { const s=JSON.parse(localStorage.getItem(KEY)); if(s && typeof s.started==='boolean' && Number.isFinite(s.runes) && Number.isFinite(s.xp) && Number.isFinite(s.last) && Array.isArray(s.owned)) state={...defaults,...s,path:s.path==='explore'?'explore':'gather'}; } catch {}
const gear=[{id:'cape',name:'Infernal Cape',type:'Capes',icon:'♜',cost:80},{id:'helm',name:'Abyssal Helm',type:'Hats',icon:'♞',cost:120},{id:'blade',name:'Dragon Blade',type:'Weapons',icon:'⚔',cost:180},{id:'armor',name:'Royal Platebody',type:'Armor',icon:'♖',cost:240}];
const tiers=[['Air',1,'#ddd','◆'],['Mind',5,'#d9b952','♦'],['Water',10,'#5367fb','♦'],['Fire',20,'#e15332','♨'],['Nature',35,'#75a64d','♠'],['Death',50,'#ddd','☠'],['Blood',75,'#ab3232','♦'],['Soul',100,'#a362cf','✧']];
let filter='All',toastTimer;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Browser storage is unavailable; progress lasts for this visit.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function rewards(){const mins=state.started?Math.min(480,Math.max(0,(Date.now()-state.last)/60000)):0;return {runes:mins*(state.path==='gather'?6:3),xp:mins*(state.path==='gather'?2:5)}}
function settle(){const r=rewards();state.runes+=r.runes;state.xp+=r.xp;state.last=Date.now();save();return r}
function start(){if(state.started){toast('Your expedition is already running. Choose a path below.');$('.player').scrollIntoView({behavior:'smooth'});return}state.started=true;state.last=Date.now();save();render();toast('Welcome, adventurer. Your journey begins with 120 runes!')}
function render(){const level=1+Math.floor(state.xp/60),r=rewards();$('#level').textContent=level;$('#rank').textContent=level>=20?'Adept':level>=5?'Apprentice':'Novice';$('#xp').textContent=`${Math.floor(state.xp%60)} / 60 experience`;$('#xpbar').style.width=`${state.xp%60/60*100}%`;$('#player-name').textContent=state.started?'Rune Traveler':'Wandering Soul';$('.rune-count').textContent=state.started?Math.floor(state.runes).toLocaleString():0;$('#balance').textContent=`${state.started?Math.floor(state.runes):0} runes`;$('#equipped').textContent=state.equipped;$('#start').textContent=state.started?'Journey Active':'Enter Demo';$('#begin').textContent=state.started?'View Your Expedition →':'Begin Your Journey →';$('#pending').textContent=`+${Math.floor(r.runes)}`;$('#path-name').textContent=state.path==='gather'?'Gathering':'Exploring';$('#rate').textContent=`${state.path==='gather'?6:3} runes / minute`;$('#status').textContent=state.started?'Expedition active · Claim rewards to level up.':'Enter the demo to start your expedition.';document.querySelectorAll('[data-path]').forEach(b=>b.classList.toggle('selected',b.dataset.path===state.path));$('#tiers').innerHTML=tiers.map(([name,l,color,icon])=>`<div class="tier ${level<l?'locked':''}"><div class="rune" style="color:${color}">${icon}</div><small>Lv. ${l}</small>${name}</div>`).join('');renderShop()}
function renderShop(){$('#items').innerHTML=gear.filter(g=>filter==='All'||g.type===filter).map(g=>`<article class="item"><span class="icon">${g.icon}</span><h3>${g.name}</h3><small>${g.type}</small><button data-buy="${g.id}">${state.equipped===g.name?'Equipped':state.owned.includes(g.id)?'Equip':`♦ ${g.cost} runes`}</button></article>`).join('')}
$('#start').onclick=start;$('#begin').onclick=start;
$('#claim').onclick=()=>{if(!state.started)return start();const r=rewards();if(r.runes<1)return toast('Your expedition is underway. The first rune arrives shortly.');settle();render();toast(`Claimed ${Math.floor(r.runes)} runes and ${Math.floor(r.xp)} experience.`)};
document.querySelectorAll('[data-path]').forEach(b=>b.onclick=()=>{if(!state.started)return toast('Enter the demo to choose an expedition.');settle();state.path=b.dataset.path;save();render();toast('Expedition changed. Previous rewards were collected.')});
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderShop()});
$('#items').onclick=e=>{const b=e.target.closest('[data-buy]');if(!b)return;const g=gear.find(g=>g.id===b.dataset.buy);if(!state.started)return toast('Enter the demo to visit the equipment shop.');if(!state.owned.includes(g.id)){if(state.runes<g.cost)return toast('Gather more runes before purchasing this item.');state.runes-=g.cost;state.owned.push(g.id)}state.equipped=g.name;save();render();toast(`${g.name} equipped.`)};
$('#collection').onclick=()=>{$('#owned').innerHTML=state.owned.length?gear.filter(g=>state.owned.includes(g.id)).map(g=>`<p>${g.icon} ${g.name}${state.equipped===g.name?' — Equipped':''}</p>`).join(''):'<p>Your collection awaits. Visit the shop to acquire your first piece of gear.</p>';$('#modal').showModal()};$('#close').onclick=()=>$('#modal').close();render();setInterval(()=>{$('#pending').textContent=`+${Math.floor(rewards().runes)}`},1000);
